{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "web" });
  const out = [];
  for (const i of issues) {
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    out.push({ shortId: i.shortId, count: i.count, status: i.status, project: i.project, nEvents: events.length, firstEvent: events[0] ?? null, allReleases: events.map(e => e.release) });
  }
  return { total: issues.length, out };
}", "input": {}}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "web" });
  const rows = [];
  for (const i of issues) {
    if (i.count < 0) continue;
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    let newest: { timestamp: string; release: string } | null = null;
    for (const e of events) {
      if (newest === null || Date.parse(e.timestamp) > Date.parse(newest.timestamp)) {
        newest = { timestamp: e.timestamp, release: e.release };
      }
    }
    rows.push({
      shortId: i.shortId,
      count: i.count,
      status: i.status,
      latestRelease: newest === null ? null : newest.release,
    });
  }
  rows.sort((a, b) => b.count - a.count);
  return rows;
}", "input": {}}
